#ifndef SCOPE_DOOM_SOUND_H
#define SCOPE_DOOM_SOUND_H

#include <stdint.h>

// Sound on the SCOPE's CV OUT jack, generated by the LGT8F328P's 8-bit DAC on
// D4 (the solder jumper must be set to the LGT8F DAC side). One Timer2
// interrupt at SOUND_RATE mixes two effect voices and three music voices
// (bass, power-chord fifth, drums). The same interrupt clocks the encoder and
// the button, so it runs on every board, with or without a DAC.
//
// The jack is unipolar (0..VCC): while sound is on it idles at mid scale
// (about +2.5 V) and the audio swings around that.

#define SOUND_RATE 16000UL

enum {
  SFX_NONE = 0,
  SFX_SHOTGUN, SFX_PUMP1, SFX_PUMP2, SFX_PUNCH, SFX_PUNCH_HIT,
  SFX_ENEMY_DIE, SFX_ALERT, SFX_FIREBALL, SFX_HURT,
  SFX_MEDKIT, SFX_MEDKIT2, SFX_MEDKIT3, SFX_SHELLS, SFX_SHELLS2,
  SFX_SECRET, SFX_STEP, SFX_MENU, SFX_CONFIRM, SFX_CONFIRM2,
  SFX_DEATH, SFX_WIN, SFX_WIN2, SFX_WIN3, SFX_SPEED,
  SFX_COUNT
};

enum { SONG_NONE = 0, SONG_TITLE, SONG_LEVEL, SONG_BOSS, SONG_COUNT };

void sound_setup(bool dacAvailable);   // starts the timer (also needed for input)
void sound_set_mode(uint8_t mode);     // 0 off, 1 effects, 2 effects + music
void sound_play(uint8_t sfx);
void sound_music(uint8_t song);
void sound_pause(bool paused);         // mute while the game is paused
void sound_stop_timer();               // before a soft reset

#ifdef HOST
void    sound_isr();                   // the harness calls this SOUND_RATE times a second
uint8_t sound_dac();                   // last value written to the DAC
void    host_log(const char *what, int v);
#endif

#endif
